#!/usr/bin/env python3
"""
Round 193o (culprits), 13 October 2026. Needs round 192o.

Surveillance companies (Surveillance Watch).

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 193o (13 October)\n\nNeeds round 192o (guards on its heading). Tiles patch round193o_tiles.py\nbeside it. No app.js?v= bump.\n\n- surveillance_entities and surveillance_links (geojsonlive; tiles\n  surveillance/entities.geojson and links.geojson, made weekly by tiles\n  surveillance_watch.py from surveillancewatch.io/api/v1/: entities,\n  entity-types, countries, cities, funders, financial-markets, each kept\n  whole in surveillance/raw/). The owner read the docs page as permission\n  ("This API enables you to integrate our data with your own endpoints");\n  no licence is stated. Entities at their headquarters city, else the\n  point the API gives for the headquarters country; lines to every country\n  or entity in surveilling and providingTo. The response shape was taken\n  from the docs (items arrays, ids or records); tested only on stand-in\n  data, as the site is blocked from the sandbox: build.json lists the\n  fields seen and the first entity\'s surveilling as given.\n  Filed under Suppression by information > Surveillance.\n']


DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round193o: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 192o" not in h.read_text(encoding="utf-8"):
        sys.exit("round193o: round 192o must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round193o: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round193o: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round193o: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
